package com.fitlife.usuario.security;
import com.fasterxml.jackson.databind.ObjectMapper;import java.math.BigInteger;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.interfaces.RSAPublicKey;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component public class JwtKeyService {
 private final KeyPair pair;private final ObjectMapper mapper;private final String issuer;private final long duration;
 public JwtKeyService(ObjectMapper mapper,@Value("${fitlife.jwt.issuer}")String issuer,@Value("${fitlife.jwt.duration-seconds:28800}")long duration){this.mapper=mapper;this.issuer=issuer;this.duration=duration;try{KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);pair=g.generateKeyPair();}catch(GeneralSecurityException e){throw new IllegalStateException("Não foi possível inicializar as chaves JWT",e);}}
 public String emitir(long id,String email){try{Instant now=Instant.now();Map<String,Object> header=Map.of("alg","RS256","typ","JWT","kid","fitlife-runtime-key");Map<String,Object> claims=new LinkedHashMap<>();claims.put("iss",issuer);claims.put("sub",Long.toString(id));claims.put("usuarioId",Long.toString(id));claims.put("email",email);claims.put("iat",now.getEpochSecond());claims.put("exp",now.plusSeconds(duration).getEpochSecond());claims.put("scope","fitlife.user");String h=enc(mapper.writeValueAsBytes(header)),p=enc(mapper.writeValueAsBytes(claims));String input=h+"."+p;Signature signature=Signature.getInstance("SHA256withRSA");signature.initSign(pair.getPrivate());signature.update(input.getBytes(StandardCharsets.US_ASCII));return input+"."+enc(signature.sign());}catch(Exception e){throw new IllegalStateException("Não foi possível emitir token de acesso",e);}}
 public Map<String,Object> jwks(){RSAPublicKey key=(RSAPublicKey)pair.getPublic();Map<String,Object> jwk=new LinkedHashMap<>();jwk.put("kty","RSA");jwk.put("use","sig");jwk.put("alg","RS256");jwk.put("kid","fitlife-runtime-key");jwk.put("n",enc(unsigned(key.getModulus())));jwk.put("e",enc(unsigned(key.getPublicExponent())));return Map.of("keys",List.of(jwk));}
 private byte[] unsigned(BigInteger i){byte[] b=i.toByteArray();return b.length>1&&b[0]==0?Arrays.copyOfRange(b,1,b.length):b;}private String enc(byte[] b){return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
}
